csui.define('csui/controls/form/fields/alpaca/alpcsuicolorpickerfield',['module', 'csui/lib/underscore', 'csui/lib/jquery',
	'csui/lib/backbone', 'csui/lib/marionette', 'csui/lib/alpaca/js/alpaca.lite',
	'csui/controls/form/fields/color.picker.field.view',	'csui/controls/form/fields/alpaca/alpcsuifield' ],
	function (module, _, $, Backbone, Marionette, Alpaca, ColorPickerFieldView, Field) {

		var colorField = Field.extend({
			
			getFieldType: function () {
				return "csui-color-picker";
			},

			showField: function () {
				return this._showField(ColorPickerFieldView);
			},

			setValue: function (value) {
				Alpaca.Fields.TextField.prototype.setValue.call(this, value);
				this.csuiValue = value;
			},

		});

		Alpaca.registerFieldClass("csui-color-picker", colorField);

		return colorField;
	});