csui.define('csui/controls/form/fields/alpaca/alpcsuiimagepickerfield',['csui/lib/alpaca/js/alpaca.lite',
	'csui/controls/form/fields/image.picker.field.view',
	'csui/controls/form/fields/alpaca/alpcsuifield' ],
	function(Alpaca, ImagePickerFieldView, Field) {

	var ImageField = Field.extend({

		getFieldType : function() {
			return "csui-image-picker";
		},

		showField : function() {
			return this._showField(ImagePickerFieldView);
		}
	});

	Alpaca.registerFieldClass("csui-image-picker", ImageField);

	return ImageField;
});
