csui.define('csui/utils/usersettings/impl/usersettings.model',['csui/lib/jquery',
    'csui/lib/underscore',
    'csui/lib/backbone',
    'csui/utils/url',
    'csui/models/mixins/connectable/connectable.mixin',
    'csui/models/mixins/fetchable/fetchable.mixin',
    'csui/models/mixins/uploadable/uploadable.mixin'
  ],
  function ($, _, Backbone, Url, ConnectableMixin, FetchableMixin, UploadableMixin) {
    "use strict";

    // only handles the 'accessibleMode' and 'responsiveContainerMode',
    // 'responsiveContainerMessageMode' for now
    var UserSettingsModel = Backbone.Model.extend({

      constructor: function (options) {
        Backbone.Model.prototype.constructor.apply(this, arguments);
        this.set({id: options.userid},{silent: true}); // set some .id so the model not considered new anymore. PUT will be used for saving
        this.makeConnectable(options);
        this.makeUploadable(options);
      },

      validate: function () {
        var errMsg, requestObj;
        var ok = true;

        if (!(this.get("requestObj"))) {
          ok = false;
          errMsg = "requestObj does not exists.";
        } else {
          requestObj = this.get("requestObj");
        }

        if (ok) {
          if (!!(requestObj.SmartUI) && !!(requestObj.General)) {
            ok = false;
            errMsg = "requestObj does not contain the expectected settings.";
          }
        }

        if (!ok){
          console.log(errMsg);
          return errMsg;
        }
      },

      url: function () {
        var url = Url.combine(this.connector.getConnectionUrl().getApiBase('v2'), 'members/preferences');
        url = Url.appendQuery(url, "metadata=true&config_name=SmartUI&config_name=General"); // query part will be trimmed for PUT calls
        return url;
      },

      parse: function(response, options) {
        if (Array.isArray(response.results)) {
          // GET
          let data = response.results[0].data, generalData ;
          if(response.results[1]){
            generalData = response.results[1].data;
          }
          // variable for accessibleMode
          var accessibleMode = false;

          if (data && data.config_name === 'SmartUI') {
            accessibleMode = data.preferences.accessibleMode;
          }  else {
            // TODO console.log("could not read accessibleMode in response, defaulting to 'false'");
          }

          // variable for responsiveContainerMode
          var responsiveContainerMode = false;
          if (data && data.config_name === 'SmartUI') {
            responsiveContainerMode = !!data.preferences.responsiveContainerMode;
          }

          // variable for responsiveContainerMode
          var responsiveContainerMessageMode = false;
          if (data && data.config_name === 'SmartUI') {
            responsiveContainerMessageMode = !!data.preferences.responsiveContainerMessageMode;
          }

          // variables are for content management
          var hasContentMgrPriv = false, contentMgtMode;
          if(generalData && generalData.config_name === 'General' 
            &&  generalData.preferences && generalData.preferences.HasContentMgrPriv){
              hasContentMgrPriv = generalData.preferences.HasContentMgrPriv;
              if(hasContentMgrPriv){
                contentMgtMode = data.preferences.General;
              }
          }

          return {
              'accessibleMode': accessibleMode, 
              'metadataLangType': (generalData && generalData.preferences)? generalData.preferences.metadataLangType : '', // to maintain metadata
              'localeType': (generalData && generalData.preferences)? generalData.preferences.localeType : '', // to maintain local
              'responsiveContainerMode': responsiveContainerMode,
              'responsiveContainerMessageMode': responsiveContainerMessageMode,
              'hasContentMgrPriv': hasContentMgrPriv,
              'contentMgtMode': contentMgtMode,
              'isInContentMgrMode': (generalData && generalData.preferences)? generalData.preferences.IsInContentMgrMode:false, // to enable and disable content manager mode
            };

        } else {
          // PUT
          var self = response.links.data.self;
          if (self.method !== 'PUT' || self.body.length!==0) {
            // error response, what to do here
            // TODO console.log('incomprehensible response of PUT');
          } else {
            return {};
          }
        }
      },

      // massage for upload to the server
      prepare: function (data, options) {
        return data.requestObj;
      }
    });

    ConnectableMixin.mixin(UserSettingsModel.prototype);
    FetchableMixin.mixin(UserSettingsModel.prototype);
    UploadableMixin.mixin(UserSettingsModel.prototype);
    
    return UserSettingsModel;

  });